const b = $input.first().json.body ?? $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const branches = { 'la-fria': 'La Fría', colon: 'Colón' };
const date = b.date
  ? new Date(b.date).toLocaleDateString('es-CO', { timeZone: 'America/Bogota', day: '2-digit', month: '2-digit', year: 'numeric' })
  : 'fecha desconocida';
const bs = Number(b.cash_bs).toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const text =
  `⚠️ <b>Alerta</b>, la caja número <b>${esc(b.checkout_number)}</b> (${esc(b.cashier || 'sin cajero')}) ` +
  `tiene bolívares en efectivo (${date}).\n` +
  `Sucursal: ${esc(branches[b.branch] ?? b.branch)}\n` +
  `Monto: <b>${bs} Bs</b>\n` +
  `Probable error: efectivo COP registrado como bolívares. Revisar el cuadre y asignar la tasa en el dashboard.`;
return [{ json: { text } }];
